//     /*! @brief Implementation details needed. $$ */
// }
//
// $Singleton$::$Singleton$() {
//     /*! @brief Implementation details needed. $$ */
// }

$$
/** @example Example usage
 * @code
 * int main() {
 * $Singleton$& instance = $Singleton$::getInstance();
 * instance.doSomething();
 * return 0;
 * }
 * @endcode
 */


/// @brief Forward declaration for Product.
class $Product$;

/**
 * @class Product
 * @brief Defines the interface for objects created by the factory method.
 */
class $Product$ {
public:
    /**
     * @brief Virtual destructor.
     */
    virtual ~$Product$() = default;

    /**
     * @brief Pure virtual method representing the product's operation.
     */
    virtual void use() = 0;
};

/**
 * @class ConcreteProductA
 * @brief Concrete implementation of the Product interface.
 */
class $ConcreteProductA$ : public $Product$ {
public:
    /**
     * @brief Overridden operation for ConcreteProductA.
     */
    void use() override; // Declaration only
};

/**
 * @class ConcreteProductB
 * @brief Concrete implementation of the Product interface.
 */
class $ConcreteProductB$ : public $Product$ {
public:
    /**
     * @brief Overridden operation for ConcreteProductB.
     */
    void use() override; // Declaration only
};

/**
 * @class Creator
 * @brief Declares the factory method, which returns an object of type Product.
 * @details May also define a default implementation of the factory method.
 */
class $Creator$ {
public:
    /**
     * @brief Virtual destructor.
     */
    virtual ~$Creator$() = default;

    /**
     * @brief The factory method. Subclasses override this to create specific products.
     * @return Pointer to the created Product. Ownership might vary (raw pointer shown).
     */
    virtual $Product$* createProduct() = 0;

    /**
     * @brief An operation that uses the product created by the factory method.
     */
    void someOperation(); // Declaration only
};

/**
 * @class ConcreteCreatorA
 * @brief Overrides the factory method to return an instance of ConcreteProductA.
 */
class $ConcreteCreatorA$ : public $Creator$ {
public:
    /**
     * @brief Factory method implementation for ConcreteProductA.
     * @return Pointer to a new ConcreteProductA.
     */
    $Product$* createProduct() override; // Declaration only
};

/**
 * @class ConcreteCreatorB
 * @brief Overrides the factory method to return an instance of ConcreteProductB.
 */
class $ConcreteCreatorB$ : public $Creator$ {
public:
    /**
     * @brief Factory method implementation for ConcreteProductB.
     * @return Pointer to a new ConcreteProductB.
     */
    $Product$* createProduct() override; // Declaration only
};

