/// @brief Forward declarations for abstract products.
class $AbstractProductA$;
class $AbstractProductB$;

/**
 * @class AbstractProductA
 * @brief Interface for a family of product objects (Type A).
 */
class $AbstractProductA$ {
public:
    virtual ~$AbstractProductA$() = default;
    /** @brief Operation specific to Product A. */
    virtual void useA() = 0;
};

/**
 * @class AbstractProductB
 * @brief Interface for a family of product objects (Type B).
 */
class $AbstractProductB$ {
public:
    virtual ~$AbstractProductB$() = default;
    /** @brief Operation specific to Product B. */
    virtual void useB() = 0;
};

/** @class ConcreteProductA1
 * @brief Concrete implementation of AbstractProductA (Variant 1). */
class $ConcreteProductA1$ : public $AbstractProductA$ {
public:
    void useA() override; // Declaration only
};

/** @class ConcreteProductA2
 * @brief Concrete implementation of AbstractProductA (Variant 2). */
class $ConcreteProductA2$ : public $AbstractProductA$ {
public:
    void useA() override; // Declaration only
};

/** @class ConcreteProductB1
 * @brief Concrete implementation of AbstractProductB (Variant 1). */
class $ConcreteProductB1$ : public $AbstractProductB$ {
public:
    void useB() override; // Declaration only
};

/** @class ConcreteProductB2
 * @brief Concrete implementation of AbstractProductB (Variant 2). */
class $ConcreteProductB2$ : public $AbstractProductB$ {
public:
    void useB() override; // Declaration only
};

/**
 * @class AbstractFactory
 * @brief Interface for creating families of related or dependent objects.
 */
class $AbstractFactory$ {
public:
    virtual ~$AbstractFactory$() = default;
    /** @brief Creates a Product A object. */
    virtual $AbstractProductA$* createProductA() = 0;
    /** @brief Creates a Product B object. */
    virtual $AbstractProductB$* createProductB() = 0;
};

/**
 * @class ConcreteFactory1
 * @brief Implements the operations to create concrete product objects (Variant 1).
 */
class $ConcreteFactory1$ : public $AbstractFactory$ {
public:
    $AbstractProductA$* createProductA() override; // Declaration only
    $AbstractProductB$* createProductB() override; // Declaration only
};

/**
 * @class ConcreteFactory2
 * @brief Implements the operations to create concrete product objects (Variant 2).
 */
class $ConcreteFactory2$ : public $AbstractFactory$ {
public:
    $AbstractProductA$* createProductA() override; // Declaration only
    $AbstractProductB$* createProductB() override; // Declaration only
};

