/** @fn $AbstractProductB$* $ConcreteFactory2$::createProductB() */
$AbstractProductB$* $ConcreteFactory2$::createProductB() /* override */ { /*! @brief Original: return new $ConcreteProductB2$(); $$ */ return nullptr; }

/** @example Example usage
