#include <string> // Needed for std::string
#include <memory> // Needed for std::unique_ptr

/// @brief Forward declarations.
class $Product$;
class $Builder$;

/**
 * @class Product
 * @brief Represents the complex object being built.
 */
class $Product$ {
public:
    $Product$();  // Declaration
    ~$Product$(); // Declaration

    /** @brief Sets Part A of the product. @param partA Value for Part A. */
    void setPartA(const std::string& partA); // Declaration only
    /** @brief Sets Part B of the product. @param partB Value for Part B. */
    void setPartB(const std::string& partB); // Declaration only
    /** @brief Lists the parts of the constructed product. */
    void listParts() const; // Declaration only
private:
    /// @brief Part A of the product.
    std::string partA_;
    /// @brief Part B of the product.
    std::string partB_;
};

/**
 * @class Builder
 * @brief Abstract interface for creating parts of a Product object.
 */
class $Builder$ {
public:
    virtual ~$Builder$() = default;
    /** @brief Builds Part A of the product. */
    virtual void buildPartA() = 0;
    /** @brief Builds Part B of the product. */
    virtual void buildPartB() = 0;
    /** @brief Retrieves the constructed product.
     * @return A unique pointer to the constructed Product. The builder might reset itself. */
    virtual std::unique_ptr<$Product$> getProduct() = 0;
};

/**
 * @class ConcreteBuilder
 * @brief Constructs and assembles parts of the product by implementing the Builder interface.
 */
class $ConcreteBuilder$ : public $Builder$ {
public:
    $ConcreteBuilder$(); // Declaration only
    ~$ConcreteBuilder$() override; // Declaration only

    void buildPartA() override; // Declaration only
    void buildPartB() override; // Declaration only
    std::unique_ptr<$Product$> getProduct() override; // Declaration only
private:
    /// @brief The product being built.
    std::unique_ptr<$Product$> product_;
};

/**
 * @class Director
 * @brief Constructs an object using the Builder interface.
 */
class $Director$ {
public:
    /** @brief Sets the builder to be used. @param builder Pointer to the builder instance. */
    void setBuilder($Builder$* builder); // Declaration only
    /** @brief Constructs the product using the current builder.
     * @return A unique pointer to the fully constructed Product. */
    std::unique_ptr<$Product$> construct(); // Declaration only
private:
    /// @brief Pointer to the builder instance used for construction.
    $Builder$* builder_;
};

// --- Implementation (Example, expected in .cpp) ---

/** @fn void $Product$::setPartA(const std::string& partA) */
void $Product$::setPartA(const std::string& partA) { /*! @brief Implementation needed. $$ */ }
/** @fn void $Product$::setPartB(const std::string& partB) */
void $Product$::setPartB(const std::string& partB) { /*! @brief Implementation needed. $$ */ }
/** @fn void $Product$::listParts() const */
void $Product$::listParts() const { /*! @brief Implementation needed. $$ */ }
/** @fn $Product$::$Product$() */
$Product$::$Product$() { /*! @brief Implementation needed. $$ */ }
/** @fn $Product$::~$Product$() */
$Product$::~$Product$() { /*! @brief Implementation needed. $$ */ }

/** @fn void $ConcreteBuilder$::buildPartA() */
void $ConcreteBuilder$::buildPartA() /* override */ { /*! @brief Implementation needed. $$ */ }
/** @fn void $ConcreteBuilder$::buildPartB() */
void $ConcreteBuilder$::buildPartB() /* override */ { /*! @brief Implementation needed. $$ */ }
/** @fn std::unique_ptr<$Product$> $ConcreteBuilder$::getProduct() */
std::unique_ptr<$Product$> $ConcreteBuilder$::getProduct() /* override */ { /*! @brief Implementation needed. $$ */ return nullptr; }
/** @fn $ConcreteBuilder$::$ConcreteBuilder$() */
$ConcreteBuilder$::$ConcreteBuilder$() { /*! @brief Implementation needed. $$ */ }
/** @fn $ConcreteBuilder$::~$ConcreteBuilder$() */
$ConcreteBuilder$::~$ConcreteBuilder$() /* override */ { /*! @brief Implementation needed. $$ */ }

/** @fn void $Director$::setBuilder($Builder$* builder) */
void $Director$::setBuilder($Builder$* builder) { /*! @brief Implementation needed. $$ */ }
/** @fn std::unique_ptr<$Product$> $Director$::construct() */
std::unique_ptr<$Product$> $Director$::construct() { /*! @brief Implementation needed. $$ */ return nullptr; }


/** @example Example usage
 * @code
 * int main() {
 * $Director$ director;
 * $ConcreteBuilder$ builder;
 * director.setBuilder(&builder);
 * std::unique_ptr<$Product$> product = director.construct();
 * if (product) { product->listParts(); }
 * return 0;
 * }
 * @endcode
 */


