/// @brief Forward declaration.
class $Prototype$;

/**
 * @class Prototype
 * @brief Declares an interface for cloning itself.
 */
class $Prototype$ {
public:
    virtual ~$Prototype$() = default;
    /** @brief Creates a clone of the object.
     * @return A unique pointer to the new cloned object. */
    virtual std::unique_ptr<$Prototype$> clone() const = 0;
    /** @brief An example operation performed by the prototype. */
    virtual void operation() = 0;
};

/**
 * @class ConcretePrototypeA
 * @brief Implements an operation for cloning itself.
 */
class $ConcretePrototypeA$ : public $Prototype$ {
public:
    /** @brief Constructor. @param value Initial value for the prototype. */
    explicit $ConcretePrototypeA$(int value); // Declaration only
    /** @brief Copy constructor (often needed for cloning). @param other Object to copy from. */
    $ConcretePrototypeA$(const $ConcretePrototypeA$& other); // Declaration only

    std::unique_ptr<$Prototype$> clone() const override; // Declaration only
    void operation() override; // Declaration only
private:
    /// @brief Example member data.
    int value_;
};

/**
 * @class ConcretePrototypeB
 * @brief Implements an operation for cloning itself.
 */
class $ConcretePrototypeB$ : public $Prototype$ {
public:
    /** @brief Constructor. @param label Initial label for the prototype. */
    explicit $ConcretePrototypeB$(std::string label); // Declaration only
     /** @brief Copy constructor (often needed for cloning). @param other Object to copy from. */
    $ConcretePrototypeB$(const $ConcretePrototypeB$& other); // Declaration only

    std::unique_ptr<$Prototype$> clone() const override; // Declaration only
    void operation() override; // Declaration only
private:
     /// @brief Example member data.
    std::string label_;
};

