/// @brief Forward declarations.
class $Target$;
class $Adaptee$;

/**
 * @class Target
 * @brief Defines the domain-specific interface that Client uses.
 */
class $Target$ {
public:
    virtual ~$Target$() = default;
    /** @brief The request method expected by the client. */
    virtual void request() = 0;
};

/**
 * @class Adaptee
 * @brief Defines an existing interface that needs adapting.
 */
class $Adaptee$ {
public:
    /** @brief The specific request method of the Adaptee. */
    void specificRequest(); // Declaration only
};

/**
 * @class Adapter
 * @brief Adapts the interface of Adaptee to the Target interface (Object Adapter).
 */
class $Adapter$ : public $Target$ {
public:
    /** @brief Constructor taking a pointer to the Adaptee.
     * @param adaptee Pointer to the Adaptee instance to adapt. */
    explicit $Adapter$($Adaptee$* adaptee); // Declaration only (raw pointer)
    // Or: explicit $Adapter$(std::shared_ptr<$Adaptee$> adaptee); // (smart pointer)

    /** @brief Implements the Target interface by calling the Adaptee's method. */
    void request() override; // Declaration only
private:
    /// @brief Pointer to the Adaptee instance.
    $Adaptee$* adaptee_; // (raw pointer)
    // Or: std::shared_ptr<$Adaptee$> adaptee_; // (smart pointer)
};

// --- Implementation (Example, expected in .cpp) ---

