// Or: $Adapter$::$Adapter$(std::shared_ptr<$Adaptee$> adaptee) : adaptee_(adaptee) { /* $$ */ }

/** @fn void $Adapter$::request() */
void $Adapter$::request() /* override */ { /*! @brief Implementation needed. (Original: adaptee_->specificRequest();) $$ */ }


