/**
 * @class Implementor
 * @brief Defines the interface for implementation classes.
 */
class $Implementor$ {
public:
    virtual ~$Implementor$() = default;
    /** @brief The implementation-specific operation. */
    virtual void operationImp() = 0;
};

/** @class ConcreteImplementorA
 * @brief Concrete implementation A of the Implementor interface. */
class $ConcreteImplementorA$ : public $Implementor$ {
public:
    void operationImp() override; // Declaration only
};

/** @class ConcreteImplementorB
 * @brief Concrete implementation B of the Implementor interface. */
class $ConcreteImplementorB$ : public $Implementor$ {
public:
    void operationImp() override; // Declaration only
};

/**
 * @class Abstraction
 * @brief Defines the abstraction's interface and maintains a reference to an Implementor.
 */
class $Abstraction$ {
public:
    /** @brief Constructor taking ownership of the Implementor.
     * @param implementor A unique pointer to an Implementor instance. */
    explicit $Abstraction$(std::unique_ptr<$Implementor$> implementor); // Declaration only
    // Or: explicit $Abstraction$($Implementor$* implementor); // Non-owning

    virtual ~$Abstraction$() = default;
    /** @brief High-level operation, delegates to the Implementor. */
    virtual void operation(); // Declaration only
protected:
    /// @brief Pointer to the Implementor.
    std::unique_ptr<$Implementor$> implementor_; // Owns the implementor
    // Or: $Implementor$* implementor_; // Non-owning
};

/**
 * @class RefinedAbstraction
 * @brief Extends the interface defined by Abstraction.
 */
class $RefinedAbstraction$ : public $Abstraction$ {
public:
    /** @brief Constructor.
     * @param implementor A unique pointer to an Implementor instance. */
    explicit $RefinedAbstraction$(std::unique_ptr<$Implementor$> implementor); // Declaration only
    // Or: explicit $RefinedAbstraction$($Implementor$* implementor); // Non-owning

    /** @brief Refined operation. */
    void operation() override; // Declaration only
};

